package local.bbsgeoimporter;
import java.nio.file.*;import java.util.*;import com.google.gson.*;
final class ManyToManyAcceptance {
 static void check(boolean b,String m){ImporterAcceptance.check(b,m);}
 static String geo(String texture){var root=JsonParser.parseString(ImporterAcceptance.GEO).getAsJsonObject();var bone=new JsonObject();bone.addProperty("name","body");bone.add("pivot",JsonParser.parseString("[0,0,0]"));bone.add("cubes",new JsonArray());root.getAsJsonArray("minecraft:geometry").get(0).getAsJsonObject().getAsJsonArray("bones").add(bone);root.addProperty("texture",texture);return root.toString();}
 static void run(Path base)throws Exception{
 String token=Long.toUnsignedString(System.nanoTime(),36);Path a=base.resolve("a"),b=base.resolve("b"),shared=base.resolve("shared"),other=base.resolve("other"),config=base.resolve("config");String ar="assets/alpha/strange/"+token+".json",br="assets/beta/geo/"+token+".geo.json";ImporterAcceptance.put(a.resolve(ar),geo("cross:textures/body.png"));ImporterAcceptance.put(b.resolve(br),geo("cross:textures/body.png"));ImporterAcceptance.png(shared.resolve("assets/cross/textures/body.png"),0xff123456);ImporterAcceptance.png(other.resolve("assets/unrelated/textures/body.png"),0xffabcdef);
 var sources=new ArrayList<>(List.of(ImporterAcceptance.source("first_"+token,"First",a),ImporterAcceptance.source("second_"+token,"Second",b),ImporterAcceptance.source("provider_"+token,"Provider",shared),ImporterAcceptance.source("other_"+token,"Other",other)));
 var importer=new GeoImporter(config,x->{});check(importer.scan(sources).discovered()==2,"random IDs and structural extension Geo discovered");var initial=Map.copyOf(SharedModelAssets.bindingsForTest());check(initial.size()==2&&initial.values().stream().map(SharedModelAssets.Binding::texture).distinct().count()==1&&initial.values().stream().allMatch(v->v.texture()!=null),"two geometries independently bind one exact cross-namespace PNG");BbsCpuAcceptance.run(config.resolve("bbs/assets"),initial);
 Performance.reset();new GeoImporter(config,x->{}).scan(sources);check(initial.equals(SharedModelAssets.bindingsForTest())&&PerformanceAcceptance.count("catalog.build")==0,"hot restart restores every shared PNG consumer without class reparse");
 Path fourth=base.resolve("fourth");String cr="assets/random/geo/"+UUID.randomUUID()+".geo.json";ImporterAcceptance.put(fourth.resolve(cr),geo("unrelated:textures/body.png"));sources.add(ImporterAcceptance.source("new_"+token,"New",fourth));Performance.reset();new GeoImporter(config,x->{}).scan(sources);check(SharedModelAssets.bindingsForTest().size()==3&&PerformanceAcceptance.count("component.build")==1,"unseen fourth model mod automatically adds folder with only its closure parsed");check(!SharedModelAssets.bindingsForTest().get("New/"+cr.substring(0,cr.lastIndexOf('/'))+"/"+cr.substring(cr.lastIndexOf('/')+1,cr.length()-9)).texture().equals(initial.values().iterator().next().texture()),"same basename from unrelated namespace never cross-binds");
 ImporterAcceptance.png(shared.resolve("assets/cross/textures/body.png"),0xff997755);new GeoImporter(config,x->{}).scan(sources);for(var e:SharedModelAssets.bindingsForTest().entrySet())if(e.getKey().startsWith("First/")||e.getKey().startsWith("Second/"))check(Arrays.equals(Files.readAllBytes(config.resolve("bbs/assets").resolve(e.getValue().texture())),Files.readAllBytes(shared.resolve("assets/cross/textures/body.png"))),"changed shared PNG updates every consumer");BbsCpuAcceptance.run(config.resolve("bbs/assets"),SharedModelAssets.bindingsForTest());
 Path sharedConfig=base.resolve("multi-owner");var aliases=List.of(ImporterAcceptance.source("logical_a_"+token,"Alias A",a),ImporterAcceptance.source("logical_b_"+token,"Alias B",a),ImporterAcceptance.source("provider_"+token,"Provider",shared));var result=new GeoImporter(sharedConfig,x->{}).scan(aliases);check(result.discovered()==1&&result.failed()==0,"same physical root multiple logical mods imports once instead of dropping all models");check(ImportedModelGroups.modelKeys().stream().anyMatch(k->k.startsWith("Container - ")),"ambiguous shared container remains visibly identified");BbsCpuAcceptance.run(sharedConfig.resolve("bbs/assets"),SharedModelAssets.bindingsForTest());
 Path layers=base.resolve("layers");ImporterAcceptance.png(layers.resolve("assets/eyes/textures/eyes.png"),0xff557799);String layerGeo="{ 'minecraft:geometry':[{'description':{'identifier':'geometry.third'},'bones':[{'name':'body','cubes':[{'origin':[0,0,0],'size':[1,1,1],'uv':{'north':{'uv':[0,0],'uv_size':[1,1],'material_instance':'body'},'south':{'uv':[0,0],'uv_size':[1,1],'material_instance':'eyes'}}}]}]}],'textures':{'body':'cross:textures/body.png','eyes':'eyes:textures/eyes.png'}}";ImporterAcceptance.put(layers.resolve("assets/third/geo/layers.geo.json"),layerGeo);sources.add(ImporterAcceptance.source("layers_"+token,"Layers",layers));new GeoImporter(config,x->{}).scan(sources);check(SharedModelAssets.bindingsForTest().values().stream().filter(v->v.materials().size()==2).count()==1,"third model retains shared body and independent eye material simultaneously");BbsCpuAcceptance.run(config.resolve("bbs/assets"),SharedModelAssets.bindingsForTest());var catalog=new ResourceCatalog(sources);check(catalog.textureConsumers().values().stream().anyMatch(set->set.size()==3),"reverse texture graph retains all three consumers");Files.delete(shared.resolve("assets/cross/textures/body.png"));new GeoImporter(config,x->{}).scan(sources);ImporterAcceptance.png(shared.resolve("assets/cross/textures/body.png"),0xff135799);new GeoImporter(config,x->{}).scan(sources);check(SharedModelAssets.bindingsForTest().values().stream().filter(v->v.texture()!=null||!v.materials().isEmpty()).count()==4,"missing then restored PNG rebinds all consumers including material user");
 Path cache=base.resolve("memo.bin");Files.writeString(cache,"fingerprint content");SourceFingerprint.begin();SourceFingerprint.digest(cache);var memo=SourceFingerprint.snapshot();SourceFingerprint.end();Performance.reset();SourceFingerprint.resume(memo);try{SourceFingerprint.digest(cache);SourceFingerprint.digest(cache);check(PerformanceAcceptance.count("source.hash")==0,"prepare fingerprints cross worker boundary with zero repeated content reads");}finally{SourceFingerprint.end();}
 System.out.println("MANY TO MANY PASS: random sources/new mod/shared PNG/cross namespace/shared root/hot/context transfer");
 }
}
